SELECT (DATE_TRUNC('DAY', "REFRESH_START_AT")) AS "TIME_BUCKET", (CAST(CASE WHEN (SUM(TARGET_LAG_SEC)) = 0 OR (SUM(TARGET_LAG_SEC)) IS NULL THEN NULL ELSE CAST((SUM(ACTUAL_LAG_SEC)) AS DECIMAL(38, 15)) / CAST((SUM(TARGET_LAG_SEC)) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15))) AS "PIPE_DT_LAG_VS_TARGET" FROM (SELECT "QUALIFIED_NAME" AS QUALIFIED_NAME, "NAME" AS DYNAMIC_TABLE_NAME, "DATABASE_NAME" AS DATABASE_NAME, "SCHEMA_NAME" AS SCHEMA_NAME, "STATE" AS REFRESH_STATE, "STATE_MESSAGE" AS STATE_MESSAGE, "REFRESH_ACTION" AS REFRESH_ACTION, "REFRESH_TRIGGER" AS REFRESH_TRIGGER, "TARGET_LAG_SEC" AS TARGET_LAG_SEC, (TRY_TO_TIMESTAMP_NTZ("REFRESH_START_TIME")) AS REFRESH_START_AT, (TRY_TO_TIMESTAMP_NTZ("REFRESH_END_TIME")) AS REFRESH_END_AT, (TRY_TO_TIMESTAMP_NTZ("DATA_TIMESTAMP")) AS DATA_TIMESTAMP_AT, (DATEDIFF(SECOND, (TRY_TO_TIMESTAMP_NTZ("DATA_TIMESTAMP")), (TRY_TO_TIMESTAMP_NTZ("REFRESH_START_TIME")))) AS ACTUAL_LAG_SEC, (DATEDIFF(SECOND, (TRY_TO_TIMESTAMP_NTZ("REFRESH_START_TIME")), (TRY_TO_TIMESTAMP_NTZ("REFRESH_END_TIME")))) AS REFRESH_DURATION_SEC FROM dynamic_table_refresh_history) AS base GROUP BY (DATE_TRUNC('DAY', "REFRESH_START_AT")) ORDER BY "PIPE_DT_LAG_VS_TARGET" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
